package wsagent

import (
	"bufio"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// The Pi package ships src/index.ts plus a committed single-file bundle of it
// (dist/index.js, generated by scripts/bundle.mjs) whose first line records a
// hash of its inputs. The launcher prefers the bundle only while that hash
// still matches the checkout, so an src/ edit without a rebuild never runs old
// code. piBundleInputHash must stay byte-identical to bundleInputHash in
// scripts/bundle.mjs.
const (
	piBundleSource  = "src/index.ts"
	piBundleFile    = "dist/index.js"
	piBundleHeader  = "// ws-pi-bundle-inputs: sha256-"
	piBundleRebuild = "npm install && npm run bundle"
)

// piExtensionLoadDeps are the npm packages the source entry imports while Pi
// loads it. Packages loaded lazily by spawned helpers are not load-time deps.
var piExtensionLoadDeps = []string{"yaml", "linkedom", "ipaddr.js"}

// piBundleInputHash hashes, in sorted package-relative slash-path order, every
// src/**/*.ts and src/**/*.mjs file, src/eff_large_wordlist.txt,
// package-lock.json and scripts/bundle.mjs as "<path>\n<sha256 hex>\n".
func piBundleInputHash(pkg string) (string, error) {
	inputs := []string{"src/eff_large_wordlist.txt", "package-lock.json", "scripts/bundle.mjs"}
	src := filepath.Join(pkg, "src")
	err := filepath.WalkDir(src, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.Type().IsRegular() && (strings.HasSuffix(d.Name(), ".ts") || strings.HasSuffix(d.Name(), ".mjs")) {
			rel, err := filepath.Rel(pkg, path)
			if err != nil {
				return err
			}
			inputs = append(inputs, filepath.ToSlash(rel))
		}
		return nil
	})
	if err != nil {
		return "", err
	}
	sort.Strings(inputs)
	digest := sha256.New()
	for _, rel := range inputs {
		raw, err := os.ReadFile(filepath.Join(pkg, filepath.FromSlash(rel)))
		if err != nil {
			return "", err
		}
		sum := sha256.Sum256(raw)
		fmt.Fprintf(digest, "%s\n%s\n", rel, hex.EncodeToString(sum[:]))
	}
	return hex.EncodeToString(digest.Sum(nil)), nil
}

// piBundleHeaderHash reads the input hash recorded on the bundle's first line.
func piBundleHeaderHash(bundle string) (string, error) {
	f, err := os.Open(bundle)
	if err != nil {
		return "", err
	}
	defer f.Close()
	line, err := bufio.NewReader(f).ReadString('\n')
	if err != nil && line == "" {
		return "", err
	}
	line = strings.TrimRight(line, "\r\n")
	if !strings.HasPrefix(line, piBundleHeader) {
		return "", fmt.Errorf("%s has no input-hash header", bundle)
	}
	return strings.TrimPrefix(line, piBundleHeader), nil
}

// piBundleFresh returns nil when pkg's bundle exists and was generated from the
// current inputs; otherwise the error says why it must not be loaded.
func piBundleFresh(pkg string) error {
	bundle := filepath.Join(pkg, filepath.FromSlash(piBundleFile))
	if !fileExists(bundle) {
		return fmt.Errorf("%s is missing", piBundleFile)
	}
	recorded, err := piBundleHeaderHash(bundle)
	if err != nil {
		return err
	}
	current, err := piBundleInputHash(pkg)
	if err != nil {
		return fmt.Errorf("%s inputs unreadable: %v", piBundleFile, err)
	}
	if recorded != current {
		return fmt.Errorf("%s is stale (its sources changed after it was generated)", piBundleFile)
	}
	return nil
}

// piMissingLoadDeps lists the load-time deps Node's ancestor node_modules
// lookup cannot find from entry's directory.
func piMissingLoadDeps(entry string) []string {
	var missing []string
	for _, dep := range piExtensionLoadDeps {
		found := false
		for dir := filepath.Dir(entry); ; dir = filepath.Dir(dir) {
			if fileExists(filepath.Join(dir, "node_modules", dep, "package.json")) {
				found = true
				break
			}
			if filepath.Dir(dir) == dir {
				break
			}
		}
		if !found {
			missing = append(missing, dep)
		}
	}
	return missing
}
